// Узел появления машин: подход «Оборонная улица, восток [E]».
// Сгенерировано из параметров. Можно править и нажать «Применить код».
// Пуассоновский поток: интервалы между машинами случайные, с показательным распределением.
import type { SpawnContext, NewVehicle, ArmId, VehicleKind } from 'sim';

const RATE_VPH = 400;          // интенсивность, авт/ч
const PROFILE: { from: number; rate: number }[] = []; // профиль по времени, с → авт/ч
const ARRIVAL: 'poisson' | 'uniform' | 'platoon' = 'poisson';
const PLATOON_SIZE = 4;
// Доли машин по подходам выезда (ключ — id подхода)
const DESTINATIONS: Record<ArmId, number> = { W: 0.7, S: 0.2, N: 0.1 };
const TYPES: { kind: VehicleKind; share: number; length: [number, number] }[] = [
  { kind: 'car', share: 0.87, length: [4.2, 4.9] },
  { kind: 'van', share: 0.08, length: [5.4, 6.6] },
  { kind: 'truck', share: 0.04, length: [9, 12] },
  { kind: 'bus', share: 0.01, length: [11.5, 12.5] },
];

function rateAt(t: number): number {
  let r = RATE_VPH;
  for (const p of PROFILE) if (t >= p.from) r = p.rate;
  return r;
}

function makeVehicle(ctx: SpawnContext): NewVehicle {
  const type = ctx.pickWeighted(TYPES.map((x) => [x, x.share] as [typeof x, number]));
  return {
    destination: ctx.pick(DESTINATIONS),
    kind: type.kind,
    length: ctx.uniform(type.length[0], type.length[1]),
  };
}

export function spawn(ctx: SpawnContext): NewVehicle[] {
  const rate = rateAt(ctx.t);
  if (rate <= 0) return [];
  const m = ctx.memory as { acc?: number; need?: number };
  if (ARRIVAL === 'poisson') {
    // накопленная интенсивность до следующей машины — случайная величина с показательным распределением.
    // Моменты появления не зависят от шага симуляции, а профиль интенсивности учитывается точно
    if (m.need === undefined) m.need = -Math.log(1 - ctx.random());
    m.acc = (m.acc ?? 0) + (rate * ctx.dt) / 3600;
    const out: NewVehicle[] = [];
    while (m.acc >= m.need) {
      m.acc -= m.need;
      m.need = -Math.log(1 - ctx.random());
      out.push(makeVehicle(ctx));
    }
    return out;
  }
  m.acc = (m.acc ?? 0) + (rate * ctx.dt) / 3600;
  const batch = ARRIVAL === 'platoon' ? Math.max(1, PLATOON_SIZE) : 1;
  if (m.acc >= batch) {
    m.acc -= batch;
    return Array.from({ length: batch }, () => makeVehicle(ctx));
  }
  return [];
}

