  const prev = m.tokens[ctx.lane] ?? 1;
  const now = Math.min(1, prev + (CAPACITY_PER_LANE_VPH / 3600) * ctx.dt);
  if (now >= 1) { m.tokens[ctx.lane] = now - 1; return true; }
  m.tokens[ctx.lane] = now;
  return false;
}

